export const HOA12_CHUONG7_HANDBOOK = [{"title":"1. Kim Loại Kiềm (Nhóm IA: Li, Na, K, Rb, Cs)","icon":"🔥","content":["Cấu hình electron lớp ngoài cùng: ns<sup>1</sup>. Số oxi hóa duy nhất trong hợp chất là +1.","Năng lượng ion hóa thứ nhất nhỏ nhất trong chu kỳ, tính khử cực mạnh tăng dần từ Li đến Cs.","Bảo quản kim loại kiềm trong dầu hỏa khan (riêng Li trong sáp paraffin).","<b>Phản ứng với nước:</b> Mãnh liệt ở nhiệt độ thường: 2M + 2H<sub>2</sub>O → 2MOH + H<sub>2</sub>↑.","<b>Màu ngọn lửa:</b> Li (đỏ tía), Na (vàng tươi), K (tím lơ)."]},{"title":"2. Kim Loại Kiềm Thổ (Nhóm IIA: Be, Mg, Ca, Sr, Ba)","icon":"💧","content":["Cấu hình electron lớp ngoài cùng: ns<sup>2</sup>. Số oxi hóa duy nhất trong hợp chất là +2.","<b>Phản ứng với nước:</b> Be không phản ứng; Mg phản ứng chậm ở nhiệt độ thường, nhanh khi đun sôi; Ca, Sr, Ba phản ứng mãnh liệt giải phóng H<sub>2</sub>.","<b>Màu ngọn lửa:</b> Ca (đỏ da cam), Sr (đỏ son), Ba (lục vàng)."]},{"title":"3. Nước Cứng & Phương Pháp Làm Mềm","icon":"💎","content":["Nước cứng chứa nhiều ion Ca<sup>2+</sup> và Mg<sup>2+</sup>.","<b>Tạm thời:</b> Chứa ion HCO<sub>3</sub><sup>-</sup>. Làm mềm bằng cách đun sôi, dùng vừa đủ Ca(OH)<sub>2</sub>, NaOH, Na<sub>2</sub>CO<sub>3</sub>, Na<sub>3</sub>PO<sub>4</sub>.","<b>Vĩnh cửu:</b> Chứa ion Cl<sup>-</sup>, SO<sub>4</sub><sup>2-</sup>. Làm mềm bằng Na<sub>2</sub>CO<sub>3</sub>, Na<sub>3</sub>PO<sub>4</sub>.","<b>Toàn phần:</b> Chứa cả tính cứng tạm thời và vĩnh cửu.","<b>Phương pháp trao đổi ion:</b> Cho nước cứng qua cột chứa nhựa cationite, ion Ca<sup>2+</sup>, Mg<sup>2+</sup> được thay thế bằng ion Na<sup>+</sup> hoặc H<sup>+</sup>."]}];

// ============================================================================
// HỆ THỐNG QUẢN LÝ TIẾN ĐỘ & GAMIFICATION LOCALSTORAGE
// ============================================================================
const STORAGE_PREFIX = 'hoa12_c7_';

export interface Chuong7ExamAttempt {
  id: string;
  examId: string;
  examTitle: string;
  score: number;
  part1Score: number;
  part2Score: number;
  part3Score: number;
  correctCount: number;
  totalQuestions: number;
  durationSeconds: number;
  tabSwitchCount: number;
  autoSubmittedDueToViolation?: boolean;
  date: string;
  formattedDate: string;
  answers: Record<string | number, any>;
}

export interface Chuong7UserProgress {
  completedLessons: string[];
  examAttempts: Record<string, Chuong7ExamAttempt[]>;
  highestScores: Record<string, number>;
  totalTimeSpentSeconds: number;
  bookmarks: string[];
  streakDays: number;
  lastActiveDate: string;
  xpPoints: number;
}

export function getChuong7UserProgress(): Chuong7UserProgress {
  try {
    const saved = localStorage.getItem(`${STORAGE_PREFIX}user_progress`);
    if (saved) return JSON.parse(saved);
  } catch (e) {
    console.error('Error loading Chuong 7 progress:', e);
  }
  return {
    completedLessons: [],
    examAttempts: {},
    highestScores: {},
    totalTimeSpentSeconds: 0,
    bookmarks: [],
    streakDays: 1,
    lastActiveDate: new Date().toISOString(),
    xpPoints: 0
  };
}

export function calculateChuong7ExamScore(questionsInput: any, userAnswers: Record<string | number, any>) {
  const questions: Chuong7Question[] = Array.isArray(questionsInput) 
    ? questionsInput 
    : (questionsInput?.questions || []);

  if (!questions || questions.length === 0) {
    return { totalScore: 0, part1Score: 0, part2Score: 0, part3Score: 0, correctCount: 0, totalQuestions: 0 };
  }

  let part1Score = 0;
  let part2Score = 0;
  let part3Score = 0;
  let correctCount = 0;

  questions.forEach(q => {
    const ans = userAnswers[q.id] || userAnswers[q.number] || userAnswers[q.displayNumber];
    if (ans === undefined || ans === null) return;

    if (q.part === 1) {
      const userLetter = typeof ans === 'string' ? ans.toUpperCase().trim() : '';
      const correctLetter = (q.correctAnswer || '').toUpperCase().trim();
      const matchedOpt = q.options?.find(o => o.isCorrect)?.letter?.toUpperCase()?.trim();
      if ((correctLetter && userLetter === correctLetter) || (matchedOpt && userLetter === matchedOpt)) {
        part1Score += 0.25;
        correctCount += 1;
      }
    } else if (q.part === 2) {
      if (typeof ans === 'object' && ans !== null) {
        let correctSubCount = 0;
        ['a', 'b', 'c', 'd'].forEach(subKey => {
          const userSubVal = ans[subKey];
          if (userSubVal === undefined || userSubVal === null) return;
          const opt = q.options?.find(o => o.letter?.toLowerCase() === subKey);
          if (opt && opt.isCorrect !== undefined) {
            const actualBool = Boolean(opt.isCorrect);
            const userBool = (userSubVal === true || userSubVal === 'true' || userSubVal === 'Đúng' || userSubVal === 'dung');
            if (actualBool === userBool) correctSubCount += 1;
          }
        });
        if (correctSubCount === 1) part2Score += 0.1;
        else if (correctSubCount === 2) part2Score += 0.25;
        else if (correctSubCount === 3) part2Score += 0.5;
        else if (correctSubCount === 4) {
          part2Score += 1.0;
          correctCount += 1;
        }
      }
    } else if (q.part === 3) {
      const userText = String(ans).trim().toLowerCase().replace(',', '.');
      const correctText = String(q.correctAnswer || '').trim().toLowerCase().replace(',', '.');
      if (correctText && userText === correctText) {
        part3Score += 0.5;
        correctCount += 1;
      }
    }
  });

  const totalScore = Math.min(10, Math.round((part1Score + part2Score + part3Score) * 100) / 100);
  return {
    totalScore,
    part1Score: Math.round(part1Score * 100) / 100,
    part2Score: Math.round(part2Score * 100) / 100,
    part3Score: Math.round(part3Score * 100) / 100,
    correctCount,
    totalQuestions: questions.length
  };
}

export function getChuong7ExamHistory(examId?: string): Chuong7ExamAttempt[] {
  try {
    const key = examId ? `${STORAGE_PREFIX}history_${examId}` : `${STORAGE_PREFIX}history_all`;
    const saved = localStorage.getItem(key);
    return saved ? JSON.parse(saved) : [];
  } catch (e) {
    return [];
  }
}

export function saveChuong7ExamAttempt(attempt: Chuong7ExamAttempt) {
  try {
    const examKey = `${STORAGE_PREFIX}history_${attempt.examId}`;
    const examHist: Chuong7ExamAttempt[] = JSON.parse(localStorage.getItem(examKey) || '[]');
    examHist.unshift(attempt);
    localStorage.setItem(examKey, JSON.stringify(examHist.slice(0, 30)));

    const allKey = `${STORAGE_PREFIX}history_all`;
    const allHist: Chuong7ExamAttempt[] = JSON.parse(localStorage.getItem(allKey) || '[]');
    allHist.unshift(attempt);
    localStorage.setItem(allKey, JSON.stringify(allHist.slice(0, 50)));

    const prog = getChuong7UserProgress();
    const curHigh = prog.highestScores[attempt.examId] || 0;
    if (attempt.score > curHigh) {
      prog.highestScores[attempt.examId] = attempt.score;
    }
    prog.xpPoints += Math.round(attempt.score * 10);
    localStorage.setItem(`${STORAGE_PREFIX}user_progress`, JSON.stringify(prog));
  } catch (e) {
    console.error('Error saving exam attempt:', e);
  }
}

export function saveChuong7ExamResult(examId: string, score: number, durationSeconds: number = 0) {
  saveChuong7ExamAttempt({
    id: `att_${Date.now()}`,
    examId,
    examTitle: examId,
    score,
    part1Score: 0,
    part2Score: 0,
    part3Score: 0,
    correctCount: 0,
    totalQuestions: 28,
    durationSeconds,
    tabSwitchCount: 0,
    date: new Date().toISOString(),
    formattedDate: new Date().toLocaleDateString('vi-VN'),
    answers: {}
  });
}

export function shuffleChuong7Exam(exam: Chuong7Exam): Chuong7Exam {
  if (!exam || !exam.questions) return exam;
  const p1 = exam.questions.filter(q => q.part === 1);
  const p2 = exam.questions.filter(q => q.part === 2);
  const p3 = exam.questions.filter(q => q.part === 3);

  const shuffleArr = (arr: any[]) => {
    const res = [...arr];
    for (let i = res.length - 1; i > 0; i--) {
      const j = Math.floor(Math.random() * (i + 1));
      [res[i], res[j]] = [res[j], res[i]];
    }
    return res;
  };

  const shuffledP1 = shuffleArr(p1);
  const shuffledP2 = shuffleArr(p2);
  const shuffledP3 = shuffleArr(p3);

  let num = 1;
  const renumbered: Chuong7Question[] = [];
  [shuffledP1, shuffledP2, shuffledP3].forEach(subList => {
    subList.forEach(q => {
      renumbered.push({
        ...q,
        number: num,
        displayNumber: num
      });
      num += 1;
    });
  });

  return {
    ...exam,
    questions: renumbered
  };
}

export function getChuong7RankTitle(xp: number): string {
  if (xp >= 500) return '🏅 Bậc Thầy Hóa Học 12';
  if (xp >= 300) return '🌟 Thủ Khoa Triển Vọng';
  if (xp >= 150) return '⚡ Dũng Sĩ Luyện Đề';
  if (xp >= 50)  return '🌱 Chiến Binh Tập Sự';
  return '📚 Tân Binh Khối 12';
}


export const getRankTitle = getChuong7RankTitle;

